    "app.engineTuning.maxChatLoopIterationsHelp": "सामान्य चैट उत्तर के दौरान टूल चलाने के बाद Jenny कितनी बार रुककर फिर सोच सकती है।",
    "app.engineTuning.maxCloudSubAgentConcurrencyHelp": "क्लाउड मॉडल पर एक साथ कितने सहायक टास्क चल सकते हैं। शेड्यूलर इसे अधिकतम 3 रखता है।",
    "app.engineTuning.maxCodeIntelligenceToolCallsPerTurnHelp": "एक उत्तर में कोड विश्लेषण की कितनी टूल कॉल की जा सकती हैं।",
    "app.engineTuning.maxInlinePayloadBytesHelp": "इससे बड़ा टूल आउटपुट बातचीत में चिपकाने के बजाय फ़ाइल में सहेजकर उसका लिंक दिया जाता है।",
    "app.engineTuning.maxLoopIterationsHelp": "केवल तब उपयोग होता है जब संसाधन अनुशासन बंद हो। चैट सीमा तय न होने पर उसकी शुरुआती सीमा भी यही होती है।",
    "app.engineTuning.maxLoopWallSecondsHelp": "एक स्थानीय टर्न सक्रिय रूप से कितनी देर काम कर सकता है। आपकी अनुमति या उत्तर की प्रतीक्षा का समय इस सीमा में नहीं गिना जाता।",
    "app.engineTuning.maxSubAgentConcurrencyHelp": "स्थानीय मॉडल पर एक साथ कितने सहायक टास्क चल सकते हैं। 1 का अर्थ है एक के बाद एक।",
    "app.engineTuning.maxSubAgentLoopIterationsHelp": "हर सहायक टास्क को सोचने के कितने दौर मिलते हैं। स्थानीय और क्लाउड के लिए इसे जानबूझकर समान रखा गया है: बड़े काम में अधिक सहायक होने चाहिए, लंबे दौर नहीं।",
    "app.engineTuning.maxTaskLoopIterationsHelp": "टास्क मोड के लिए यही सीमा, जहाँ लंबे और कई चरणों वाले काम अपेक्षित हैं। डिफ़ॉल्ट पर छोड़ने पर धीमे लोकल मॉडल को चार गुना तक ज़्यादा दौर मिलते हैं।",
    "app.engineTuning.maxToolCallsPerSessionHelp": "पूरी बातचीत में टूल कॉल की सुरक्षा सीमा, ताकि नियंत्रण से बाहर लूप हमेशा न चलता रहे।",
    "app.engineTuning.maxToolsPerTurnHelp": "एक संदेश का उत्तर देते समय Jenny कितनी टूल कॉल (फ़ाइल पढ़ना, वेब खोजना आदि) कर सकती है। लंबे, टूल-प्रधान काम के लिए इसे बढ़ाएँ; तेज़ उत्तरों के लिए घटाएँ।",
    "app.engineTuning.maxWebToolCallsPerTurnHelp": "एक उत्तर में कितनी वेब खोज या पेज फ़ेच किए जा सकते हैं। केवल सफल कॉल गिनी जाती हैं; विफल कॉल की गिनती वापस मिलती है।",
    "app.engineTuning.modelLoadGraceSecondsHelp": "स्थानीय मॉडल के GPU मेमोरी में लोड होते समय पहले शब्दों के लिए कितनी देर प्रतीक्षा की जाए। बहुत बड़े मॉडल या धीमी डिस्क के लिए इसे बढ़ाएँ।",
    "app.engineTuning.ollamaRequestTimeoutSecondsHelp": "Ollama को भेजे गए एक अनुरोध को छोड़ने से पहले कितनी देर प्रतीक्षा की जाए।",
    "app.engineTuning.reasoningHelp": "हर दौर में एक मॉडल जनरेशन और उसकी माँगी हुई टूल कॉल शामिल हैं। इन्हें बढ़ाने से टर्न काटे जाने से पहले अधिक देर काम कर सकता है।",
    "app.engineTuning.spendHelp": "भुगतान वाले प्रदाता पर एक उत्तर की लागत की पक्की अधिकतम सीमा।",
    "app.engineTuning.timeoutsHelp": "किसी टूल, मॉडल लोड या अनुरोध को छोड़ने से पहले Jenny कितनी देर प्रतीक्षा करे।",
    "app.engineTuning.tokenBudgetAutoCompactRatioHelp": "जब बातचीत मॉडल की कॉन्टेक्स्ट विंडो के इस हिस्से तक भर जाती है, पुराने संदेशों का सार अपने-आप बनता है। कम मान पर सार पहले बनेगा।",
    "app.engineTuning.tokenBudgetReservedForSummaryHelp": "कम्पैक्शन से बनने वाले सार के लिए कॉन्टेक्स्ट विंडो में खाली रखी गई जगह।",
    "app.engineTuning.tokenBudgetToolOverheadHelp": "कॉन्टेक्स्ट विंडो की भरावट आँकते समय हर टूल कॉल के लिए मानी जाने वाली अतिरिक्त जगह।",
