    "diagnostics.issues.details": "विवरण",
    "diagnostics.issues.explain.engineNotice.cause": "llama.cpp, जो स्थानीय मॉडल और अर्थ से खोज का इंडेक्स चलाता है, मॉडल लोड करते समय नोट्स दिखाता है। ये आम तौर पर हानिरहित होते हैं। इन्हें तभी देखें जब कोई मॉडल लोड न हो या अजीब जवाब दे।",
    "diagnostics.issues.explain.engineNotice.title": "एक स्थानीय इंजन ने चेतावनी दिखाई",
    "diagnostics.issues.explain.engineUnreachable.cause": "सेटिंग्स में चुना गया इंजन जवाब नहीं दे रहा है, इसलिए जब तक वह जवाब नहीं देता, चैट नहीं चल सकती। उस सर्वर को शुरू करें, या सेटिंग्स में कोई दूसरा इंजन या मॉडल चुनें। विवरण में वह पता दिखता है जिसे Jenny ने आज़माया।",
    "diagnostics.issues.explain.engineUnreachable.title": "Jenny आपके मॉडल सर्वर तक नहीं पहुँच पा रहा है",
    "diagnostics.issues.explain.fallback.cause": "Jenny के पास अभी इसके लिए कोई खास सलाह नहीं है। क्या दर्ज किया गया था, यह देखने के लिए विवरण खोलें।",
    "diagnostics.issues.explain.fallback.errorTitle": "{area} ने त्रुटि की सूचना दी",
    "diagnostics.issues.explain.fallback.warningTitle": "{area} ने चेतावनी की सूचना दी",
    "diagnostics.issues.explain.noWorkspaceFolder.cause": "वर्कस्पेस ने फ़ाइलों की सूची बनाने और निगरानी करने की कोशिश की, लेकिन कोई फ़ोल्डर नहीं चुना गया है। फ़ाइल ट्री और फ़ाइल टूल इस्तेमाल करने के लिए एक फ़ोल्डर चुनें। यदि आप केवल चैट करते हैं, तो इसे अनदेखा कर सकते हैं।",
    "diagnostics.issues.explain.noWorkspaceFolder.title": "वर्कस्पेस का कोई फ़ोल्डर खुला नहीं है",
    "diagnostics.issues.explain.slowRequest.cause": "ऐप के एक अनुरोध में {duration} लगा (लक्ष्य 1 सेकंड है)। मॉडल लोड होते समय यह आम है। यदि बार-बार हो, तो प्रदर्शन से तुलना करें।",
    "diagnostics.issues.explain.slowRequest.causeNoDuration": "ऐप के एक अनुरोध में 1 सेकंड से अधिक लगा। मॉडल लोड होते समय यह आम है। यदि बार-बार हो, तो प्रदर्शन से तुलना करें।",
    "diagnostics.issues.explain.slowRequest.title": "पृष्ठभूमि का एक अनुरोध धीमा था",
    "diagnostics.issues.explain.workspaceGitFallback.cause": "Jenny वर्कस्पेस की फ़ाइलें Git से सूचीबद्ध करता है, और यहाँ वह विफल रहा, इसलिए एक सरल सूची इस्तेमाल की गई। फ़ाइल टूल अब भी काम करते हैं। कारण जानने के लिए फ़ोल्डर में git status चलाएँ; किसी दूसरे Windows उपयोगकर्ता का फ़ोल्डर होना एक आम कारण है।",
    "diagnostics.issues.explain.workspaceGitFallback.title": "Git इस वर्कस्पेस को नहीं पढ़ सका",
    "diagnostics.issues.explain.workspaceReadFailed.cause": "Jenny चुने गए फ़ोल्डर की फ़ाइलों की सूची नहीं बना सकी या उनकी निगरानी नहीं कर सकी। जाँचें कि फ़ोल्डर अभी भी मौजूद है और आप उसे खोल सकते हैं।",
    "diagnostics.issues.explain.workspaceReadFailed.title": "वर्कस्पेस फ़ोल्डर को पढ़ नहीं सका",
