    "models.tuning.tip.contextLength": "मॉडल एक बार में बातचीत, फ़ाइलों और टूल आउटपुट का कितना हिस्सा पढ़ सकता है, टोकन में (256K लगभग 1,90,000 शब्द है)। बड़ी विंडो ज़्यादा याद रखती है पर ज़्यादा VRAM लेती है। {min} से {max} तक कोई भी आकार लिखने के लिए कस्टम चुनें।",
    "models.tuning.tip.maxOutputTokens": "मॉडल को रोके जाने से पहले एक जवाब अधिकतम कितने टोकन इस्तेमाल कर सकता है (एक टोकन लगभग ¾ शब्द होता है)। खाली छोड़ने पर मॉडल का डिफ़ॉल्ट लगता है। सीमा {min}–{max}।",
    "models.tuning.tip.minP": "ऐसा हर शब्द हटा देता है जिसकी संभावना शीर्ष विकल्प के P गुना से कम हो। 0 इसे बंद करता है; 0.05 एक आम, संतुलित सेटिंग है। सीमा {min}–{max}।",
    "models.tuning.tip.presencePenalty": "पहले आ चुके हर शब्द से एक समान दूरी बनाता है। 0 बंद है; धनात्मक मान विविधता लाते हैं, ऋणात्मक मान विषय पर टिके रहते हैं। सीमा {min}–{max}।",
    "models.tuning.tip.ratio": "जब चैट कॉन्टेक्स्ट विंडो का इतना हिस्सा भर देती है, तो Jenny जगह बनाने के लिए पुराने टर्न का सारांश बनाती है। कम मान जल्दी सारांश बनाता है। {min}–{max}%, डिफ़ॉल्ट 90%।",
    "models.tuning.tip.repetitionPenalty": "पहले इस्तेमाल हुए शब्दों की संभावना घटाता है। 1 बंद है; 1.05–1.15 लूप रोकता है; 1 से कम दोहराव बढ़ाता है। सीमा {min}–{max}।",
    "models.tuning.tip.temperature": "हर शब्द का चुनाव कितना रैंडम है। 0 हमेशा सबसे संभावित शब्द चुनता है; लगभग 0.7 चैट के लिए ठीक है; 1 से ऊपर जवाब ढीले हो जाते हैं। सीमा {min}–{max}।",
    "models.tuning.tip.topK": "मॉडल केवल K सबसे संभावित अगले शब्दों में से चुनता है। 0 इसे बंद करता है; 20–40 आम है। सीमा {min}–{max}।",
    "models.tuning.tip.topP": "न्यूक्लियस सैंपलिंग: मॉडल केवल उन सबसे संभावित अगले शब्दों में से चुनता है जिनकी संभावनाओं का योग P हो। 1 इसे बंद करता है; 0.9 कम संभावित शब्द हटा देता है। सीमा {min}–{max}।",
