    "settings.about.disclosure": "Jenny सॉफ़्टवेयर है — एक टूल, जीवित प्राणी नहीं। उसके पास भावना, चेतना या इरादा नहीं है, भले उसकी बातों से ऐसा लगे। आपकी अनुमति से वह वर्कस्पेस की फ़ाइलें पढ़ और बदल सकती है तथा इस कंप्यूटर पर कमांड चला सकती है; काम के दौरान उस पर नज़र रखें और ऑटो रन को बिना निगरानी चलते न छोड़ें।",
